input.command:
node --input-type=module -e "
import { genkit } from 'genkit';
import { googleAI } from '@genkit-ai/google-genai';
const ai = genkit({ plugins: [googleAI()] });
const PRIMARY_MODEL = googleAI.model('gemini-does-not-exist-xyz');
const FALLBACK_MODEL = googleAI.model('gemini-flash-lite-latest');
const prompt = 'Tell me one short, clean joke. Respond with only the joke, no preamble.';
try {
  const r = await ai.generate({ model: PRIMARY_MODEL, prompt });
  console.log(r.text);
} catch (err) {
  console.error('Primary failed as expected:', err.message);
  const r = await ai.generate({ model: FALLBACK_MODEL, prompt });
  console.log('Fallback result:', r.text);
}
"
